<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { AlertBanner, PageHeader, RefreshButton } from './ui';
	type Customer={id:string;name:string;email:string;phone:string}; type Document={id:string;kind:string;number:string;status:string;issue_date:string;due_date?:string;total_cents:number;counterparty:string};
	let customers=$state<Customer[]>([]),documents=$state<Document[]>([]),name=$state(''),email=$state(''),phone=$state(''),customerId=$state(''),kind=$state('invoice'),description=$state(''),quantity=$state<number|null>(1),priceRupiah=$state<number|null>(null),issueDate=$state(new Date().toISOString().slice(0,10)),dueDate=$state(''),notes=$state(''),error=$state(''),notice=$state(''),saving=$state(false),loading=$state(true);
	const money=(value:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value/100); const cents=(value:number|null)=>Math.round(Number(value??0)*100); const failure=(e:unknown)=>e instanceof Error?e.message:'Perubahan tidak dapat disimpan.';
	async function load(){loading=true;try{const x=await request<{customers:Customer[];documents:Document[]}>('/v1/admin/commercial');customers=x.customers;documents=x.documents;}catch(e){error=failure(e);}finally{loading=false;}}
	async function run(label:string,task:()=>Promise<void>){error='';notice='';saving=true;try{await task();notice=`${label} berhasil disimpan.`;await load();}catch(e){error=failure(e);}finally{saving=false;}}
	function addCustomer(){return run('Customer',async()=>{await request('/v1/admin/commercial/customers',{method:'POST',body:JSON.stringify({name,email,phone})});name='';email='';phone='';});}
	function createDocument(){return run('Dokumen',async()=>{if(!description.trim()||Number(quantity)<=0||cents(priceRupiah)<0)throw new Error('Lengkapi deskripsi, jumlah, dan nominal.');await request('/v1/admin/commercial',{method:'POST',body:JSON.stringify({kind,counterparty_id:customerId||null,issue_date:issueDate,due_date:dueDate||null,notes,lines:[{description,quantity:Number(quantity),unit_price_cents:cents(priceRupiah)}]})});description='';priceRupiah=null;notes='';});}
	onMount(load);
</script>
<main class="workspace-page commercial-page"><PageHeader title="Commercial" description="Customer, quotation, invoice, tagihan vendor, dan pencatatan ke jurnal." backHref="/admin/dashboard">{#snippet actions()}<RefreshButton onclick={load} disabled={saving||loading} label="Muat ulang" />{/snippet}</PageHeader>{#if error}<AlertBanner title="Perubahan belum tersimpan" message={error}/>{/if}{#if notice}<AlertBanner variant="success" message={notice}/>{/if}
<div class="grid"><section class="panel"><h2>Customer baru</h2><p>Data customer dipakai sebagai lawan transaksi pada quotation dan invoice.</p><form novalidate onsubmit={(e)=>{e.preventDefault();void addCustomer();}}><label>Nama customer<input bind:value={name} required maxlength="180" placeholder="Nama perusahaan atau pelanggan"/></label><div class="twocol"><label>Email<input bind:value={email} type="email" placeholder="email@customer.com"/></label><label>Telepon<input bind:value={phone} type="tel" placeholder="08…"/></label></div><button disabled={saving}>Simpan customer</button></form><div class="list">{#each customers as item(item.id)}<article><strong>{item.name}</strong><small>{item.email||item.phone||'Kontak belum diisi'}</small></article>{:else}<p class="empty">Belum ada customer.</p>{/each}</div></section>
<section class="panel"><h2>Dokumen baru</h2><p>Invoice dan vendor bill akan diposting ke jurnal jika mapping akun sudah lengkap.</p><form novalidate onsubmit={(e)=>{e.preventDefault();void createDocument();}}><div class="twocol"><label>Jenis dokumen<select bind:value={kind}><option value="quote">Quotation</option><option value="invoice">Invoice</option><option value="vendor_bill">Vendor bill</option></select></label><label>Customer / vendor<select bind:value={customerId}><option value="">Tanpa lawan transaksi</option>{#each customers as item}<option value={item.id}>{item.name}</option>{/each}</select></label></div><label>Deskripsi baris<input bind:value={description} required maxlength="500" placeholder="Contoh: Jasa implementasi"/></label><div class="twocol"><label>Jumlah<input bind:value={quantity} type="number" min="1" step="1" required/></label><label>Harga satuan (Rp)<input bind:value={priceRupiah} type="number" min="0" step="1" required placeholder="0"/></label></div><div class="twocol"><label>Tanggal terbit<input bind:value={issueDate} type="date" required/></label><label>Jatuh tempo<input bind:value={dueDate} type="date"/></label></div><label>Catatan<textarea bind:value={notes} maxlength="1000" rows="2" placeholder="Opsional"></textarea></label><button disabled={saving}>Terbitkan dokumen</button></form></section></div>
<section class="panel"><header><div><h2>Dokumen terbaru</h2><p>Nominal ditampilkan dalam Rupiah. Status paid berarti pembayaran telah tercatat.</p></div></header><div class="documents">{#each documents as item(item.id)}<article><div><strong>{item.number}</strong><small>{item.kind} · {item.counterparty||'Tanpa lawan transaksi'} · {item.issue_date}</small></div><div><strong>{money(item.total_cents)}</strong><small>{item.status}</small></div></article>{:else}<p class="empty">Belum ada dokumen.</p>{/each}</div></section></main>
<style>.commercial-page{display:grid;gap:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.panel{padding:14px;border-radius:var(--radius)}h2{margin:0 0 4px;font-size:14px}.panel>p,header p,small{margin:0;color:var(--muted);font-size:11px;line-height:1.5}form{display:grid;gap:9px;margin-top:10px}label{display:grid;gap:4px;font-size:11px;font-weight:700}.twocol{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.list,.documents{margin-top:12px;border-top:1px solid var(--line)}article{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}article div:last-child{text-align:right}.empty{color:var(--muted);font-size:12px}@media(max-width:720px){.grid,.twocol{grid-template-columns:1fr}}</style>
